<script setup>
import { computed, ref } from 'vue'; import { useRouter } from 'vue-router'; import StatCard from '../components/StatCard.vue'; import { getCategoryStats, getSubcategoryStats } from '../utils/statistics'; import questions from '../data/questions.json'
const router=useRouter(); const stats=computed(()=>getCategoryStats('SIMAK UI')); const weak=computed(()=>getSubcategoryStats('SIMAK UI').sort((a,b)=>a.accuracy-b.accuracy)[0]?.subcategory||'Belum ada data'); const subs=[...new Set(questions.filter(q=>q.kategori==='SIMAK UI').map(q=>q.subkategori))]; const sub=ref('Semua')
</script>
<template><section class="page"><h1>SIMAK UI</h1><p class="lead">Latihan orisinal bergaya kemampuan akademik tanpa menyalin soal resmi.</p><div class="stat-grid"><StatCard title="Soal dikerjakan" :value="stats.answered"/><StatCard title="Akurasi SIMAK UI" :value="`${stats.accuracy}%`"/><StatCard title="Subkategori terlemah" :value="weak" tone="amber"/></div><div class="card"><h2>Filter subkategori</h2><select v-model="sub"><option>Semua</option><option v-for="s in subs" :key="s">{{ s }}</option></select><button class="btn" @click="router.push('/daily?category=SIMAK UI')">Mulai latihan SIMAK UI</button></div></section></template>
